theorem classical_capped_depth {β : Type}
    (T : OutTree (Fin r × κ) β) (c : Fin r → ℕ) (hT : T.capped c) :
    T.depth ≤ ∑ h, c h

theorem classical_capped_depth_uniform {β : Type}
    (T : OutTree (Fin r × κ) β) (L : ℕ) (hT : T.capped fun _ => L) :
    T.depth ≤ r * L

