QuarticQuery.Paper.classical_direct_product {κ : Type} [Fintype κ] [DecidableEq κ] {r : Nat}
  {f : QuarticQuery.PartialBool κ} {μ : QuarticQuery.BitInput κ → Real} {L : Nat} {β : Real}
  (hμ : ∀ (x : QuarticQuery.BitInput κ), LE.le 0 (μ x)) (hμ1 : Eq (QuarticQuery.Paper.classicalMass μ) 1)
  (hard : ∀ (T : QuarticQuery.QueryTree κ), LE.le T.depth L → LE.le (QuarticQuery.treeSuccess f μ T) β)
  (T : QuarticQuery.OutTree (Prod (Fin r) κ) (Fin r → Bool)) (hT : T.capped fun x => L) :
  LE.le (QuarticQuery.guessSuccess f (fun x => μ) T) (HPow.hPow β r)

QuarticQuery.Paper.classical_direct_product_average {κ : Type} [Fintype κ] [DecidableEq κ] {r : Nat} {S : Type}
  [Fintype S] {f : QuarticQuery.PartialBool κ} {μ : QuarticQuery.BitInput κ → Real} {L : Nat} {β : Real}
  (hμ : ∀ (x : QuarticQuery.BitInput κ), LE.le 0 (μ x)) (hμ1 : Eq (QuarticQuery.Paper.classicalMass μ) 1)
  (hard : ∀ (T : QuarticQuery.QueryTree κ), LE.le T.depth L → LE.le (QuarticQuery.treeSuccess f μ T) β) {p : S → Real}
  (hp : ∀ (s : S), LE.le 0 (p s)) (hp1 : Eq (Finset.univ.sum fun s => p s) 1)
  (T : S → QuarticQuery.OutTree (Prod (Fin r) κ) (Fin r → Bool)) (hT : ∀ (s : S), (T s).capped fun x => L) :
  LE.le (Finset.univ.sum fun s => HMul.hMul (p s) (QuarticQuery.guessSuccess f (fun x => μ) (T s))) (HPow.hPow β r)
